from collections.abc import Iterator


class Grammar:
  def __init__(
    self, T: set[str], N: set[str], P: set[tuple[str, str]], S: str
  ):
    self.T, self.N, self.P, self.S = T, N, P, S

  def L(self, log=False, stats=False) -> Iterator[str]:
    dd, d = set(), {self.S}
    if log:
      print('    ', self.S)
    while d != set():
      if stats:
        print('# added derivations:', len(d))
      if log:
        print()
      dd.update(d)
      d = set()
      for π in sorted(dd, key=len):
        for σ, τ in self.P:  # production σ → τ
          i = π.find(σ, 0)
          while i != -1:  # π == π[0:i] + σ + π[i + len(σ):]
            χ = π[0:i] + τ + π[i + len(σ) :]
            χ = χ.replace('  ', ' ')
            if (χ not in dd) and (χ not in d):
              if all(a in self.T for a in χ.split()):
                yield χ.strip()
              if log:
                print('    ', π, '⇒', χ)
              d.add(χ)
            i = π.find(σ, i + 1)
```

The method `s.strip()` removes leading and trailing spaces. The method `s.replace('  ', ' ')` is used to eliminate duplicate spaces; these occur if, say, in `X Y Z`, the production $Y \to \varepsilon$, represented by `('Y', '')`, is applied.

Grammar $G_1$ is represented by:

```python cell
G1 = Grammar(
  {'a', 'b', 'c', 'd'},
  {'S', 'X'},
  {('S', 'a X'), ('S', 'b X'), ('X', 'c'), ('X', 'd')},
  'S',
)
```
